/**
 * The inner pages' editable copy and photos: every page the website
 * prototype draws besides the homepage, one CMS section per page.
 *
 * Transcribed from the m.on website prototype (m-on-website/index.html, the
 * page builders in its logic, and js/icons.js, js/guides.js,
 * js/home-defaults.js): its English and Arabic text, and its German and
 * Turkish from the prototype's own translation tables (js/i18n-de.js,
 * js/i18n-tr.js); where those had no entry the German and Turkish were
 * written for this file. Generated — regenerate rather than hand-edit large
 * parts.
 *
 * Sections: page-services, service-moving, service-renovation, service-cleaning, service-disposal, page-about, page-why, page-how-it-works, page-locations, page-for-business, page-jobs, page-partner, page-reviews, page-faq, page-blog, page-guarantees, page-contact, page-privacy, page-terms, page-imprint.
 *
 * The blocks the prototype shares with the homepage (the closing pair, the
 * numbers, the moving types, the expectation cards, before & after, the
 * moving day) are not repeated here: the pages read them from `home`.
 * The legal pages' texts stay in legal-content.ts; this adds their frame.
 *
 * Links are site paths without the language ("/kontakt"); the page adds it.
 * Photos are files under apps/web/public/images/mon. Applying a rewrite of a
 * section to a database that already has it:
 *
 *     pnpm --filter @mon/db seed:home --section=page-about --force --prune
 */

import type { ContentSeed } from "./page-content.js";

function row(
  section: string,
  slot: string,
  kind: ContentSeed["kind"],
  label: string,
  sortOrder: number,
  values: ContentSeed["values"],
): ContentSeed {
  return { section, slot, kind, label, sortOrder, values };
}

/** A row that reads the same in every language: a path, a name, a figure. */
const same = (value: string): ContentSeed["values"] => ({ de: value, en: value, ar: value, tr: value });

